function IS_DAISY_CUBE(D):
    fam <- hash set of members of D
    for A in fam:
        for x in A:
            if (A \ {x}) not in fam:
                return False
    return True

function FORBIDDEN_MINOR(r, s):
    grid <- {0,1,2}^r ;  cube <- {0,1}^s ;  w0 <- (0,...,0)
    removed <- { ((0,...,0), w0), ((2,...,2), w0) }
    V <- { (g,w) : g in grid, w in cube } \ removed
    E <- { (p,q) : p,q in V, ADJ(p,q) }       # grid-or-cube distance 1
    return (V, E)

